//! Integration tests for the Telegram channel authorization fix.//!//! These tests verify the fix for the bug where group messages bypassed allow_from//! checks when owner_id is null. Regression tests ensure://!//! 1. When owner_id is null and dm_policy is "allowlist", unauthorized users in//!    group chats are dropped even if they @mention the bot//! 2. When owner_id is null and dm_policy is "open", all users can interact//! 3. When owner_id is set, only that user can interact//! 4. Authorization works correctly for both private and group chatsuse std::collections::HashMap;use std::sync::Arc;use ironclaw::channels::wasm::{    ChannelCapabilities, PreparedChannelModule, WasmChannel, WasmChannelRuntime,    WasmChannelRuntimeConfig,};use ironclaw::pairing::PairingStore;/// Skip the test if the Telegram WASM module hasn't been built./// In CI (detected via the `CI` env var), panic instead of skipping so a/// broken WASM build step doesn't silently produce green tests.macro_rules! require_telegram_wasm {    () => {        if !telegram_wasm_path().exists() {            let msg = format!(                "Telegram WASM module not found at {:?}. \                 Build with: cd channels-src/telegram && cargo build --target wasm32-wasip2 --release",                telegram_wasm_path()            );            if std::env::var("CI").is_ok() {                panic!("{}", msg);            }            eprintln!("Skipping test: {}", msg);            return;        }    };}/// Path to the built Telegram WASM modulefn telegram_wasm_path() -> std::path::PathBuf {    let local = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR"))        .join("channels-src/telegram/target/wasm32-wasip2/release/telegram_channel.wasm");    if local.exists() {        return local;    }    if let Ok(output) = std::process::Command::new("git")        .args(["worktree", "list", "--porcelain"])        .output()        && output.status.success()    {        let stdout = String::from_utf8_lossy(&output.stdout);        for line in stdout.lines() {            if let Some(path) = line.strip_prefix("worktree ") {                let candidate = std::path::PathBuf::from(path).join(                    "channels-src/telegram/target/wasm32-wasip2/release/telegram_channel.wasm",                );                if candidate.exists() {                    return candidate;                }            }        }    }    local}/// Create a test runtime for WASM channel operations.fn create_test_runtime() -> Arc<WasmChannelRuntime> {    let config = WasmChannelRuntimeConfig::for_testing();    Arc::new(WasmChannelRuntime::new(config).expect("Failed to create runtime"))}/// Load the real Telegram WASM module.